def __call__(self, token):
    """
        Function decorator to apply certain suppressions to a whole
        function.
        """

    @wraps(token)
    def new_func(*args, **kwargs):
        with self:
            return token(*args, **kwargs)
    return new_func

def _fit(self, X):
    """Dispatch to the right submethod depending on the chosen solver."""
    xp, is_array_api_compliant = get_namespace(X)
    if issparse(X) and self.svd_solver not in ['auto', 'arpack', 'covariance_eigh']:
        raise TypeError(f'PCA only support sparse inputs with the "arpack" and "covariance_eigh" solvers, while "{self.svd_solver}" was passed. See TruncatedSVD for a possible alternative.')
    if self.svd_solver == 'arpack' and is_array_api_compliant:
        raise ValueError("PCA with svd_solver='arpack' is not supported for Array API inputs.")
    X = validate_data(self, X, dtype=[xp.float64, xp.float32], force_writeable=True, accept_sparse=('csr', 'csc'), ensure_2d=True, copy=False)
    self._fit_svd_solver = self.svd_solver
    if self._fit_svd_solver == 'auto' and issparse(X):
        self._fit_svd_solver = 'arpack'
    if self.n_components is None:
        if self._fit_svd_solver != 'arpack':
            n_components = min(X.shape)
        else:
            n_components = min(X.shape) - 1
    else:
        n_components = self.n_components
    if self._fit_svd_solver == 'auto':
        if X.shape[1] <= 1000 and X.shape[0] >= 10 * X.shape[1]:
            self._fit_svd_solver = 'covariance_eigh'
        elif max(X.shape) <= 500 or n_components == 'mle':
            self._fit_svd_solver = 'full'
        elif 1 <= n_components < 0.8 * min(X.shape):
            self._fit_svd_solver = 'randomized'
        else:
            self._fit_svd_solver = 'full'
    if self._fit_svd_solver in ('full', 'covariance_eigh'):
        return self._fit_full(X, n_components, xp, is_array_api_compliant)
    elif self._fit_svd_solver in ['arpack', 'randomized']:
        return self._fit_truncated(X, n_components, xp)

def _set_ticklabels(ax: Axes, labels: list[str], is_vertical: bool, **kwargs) -> None:
    """Set the tick labels of a given axis.

    Due to https://github.com/matplotlib/matplotlib/pull/17266, we need to handle the
    case of repeated ticks (due to `FixedLocator`) and thus we duplicate the number of
    labels.
    """
    ticks = ax.get_xticks() if is_vertical else ax.get_yticks()
    if len(ticks) != len(labels):
        i, remainder = divmod(len(ticks), len(labels))
        if Version(mpl.__version__) < Version('3.10'):
            assert remainder == 0, remainder
        labels *= i
    if is_vertical:
        ax.set_xticklabels(labels, **kwargs)
    else:
        ax.set_yticklabels(labels, **kwargs)

def requires_deep_recursion(func):
    """Decorator to skip test if deep recursion is not supported."""
    import pytest

    @wraps(func)
    def wrapper(*args, **kwargs):
        if IS_PYSTON:
            pytest.skip('Pyston disables recursion checking')
        if IS_WASM:
            pytest.skip('WASM has limited stack size')
        if not IS_64BIT:
            pytest.skip('32 bit Python has limited stack size')
        cflags = sysconfig.get_config_var('CFLAGS') or ''
        config_args = sysconfig.get_config_var('CONFIG_ARGS') or ''
        address_sanitizer = '-fsanitize=address' in cflags or '--with-address-sanitizer' in config_args
        thread_sanitizer = '-fsanitize=thread' in cflags or '--with-thread-sanitizer' in config_args
        if address_sanitizer or thread_sanitizer:
            pytest.skip('AddressSanitizer and ThreadSanitizer do not support deep recursion')
        return func(*args, **kwargs)
    return wrapper

def __mul__(self, other):
    """Multiply self by other, and return a new masked array."""
    if self._delegate_binop(other):
        return NotImplemented
    return multiply(self, other)

def save_to_buffer(string: str, buf: FilePath | WriteBuffer[str] | None=None, encoding: str | None=None) -> str | None:
    """
    Perform serialization. Write to buf or return as string if buf is None.
    """
    with _get_buffer(buf, encoding=encoding) as fd:
        fd.write(string)
        if buf is None:
            return fd.getvalue()
        return None

def _update_strl_names(self) -> None:
    """
        Update column names for conversion to strl if they might have been
        changed to comply with Stata naming rules
        """
    for orig, new in self._converted_names.items():
        if orig in self._convert_strl:
            idx = self._convert_strl.index(orig)
            self._convert_strl[idx] = new

def _as_numpy_array(array: Array, *, xp: ModuleType) -> np.typing.NDArray[Any]:
    """
    Convert array to NumPy, bypassing GPU-CPU transfer guards and densification guards.
    """
    np = _require_numpy()
    if is_cupy_namespace(xp):
        return xp.asnumpy(array)
    if is_pydata_sparse_namespace(xp):
        return array.todense()
    if is_torch_namespace(xp):
        array = cast(Array, array.resolve_conj())
        array = to_device(array, 'cpu')
    if is_array_api_strict_namespace(xp):
        cpu: Device = xp.Device('CPU_DEVICE')
        array = to_device(array, cpu)
    if is_jax_namespace(xp):
        import jax
        cpu = cast(Device, jax.devices('cpu')[0])
        array = to_device(array, cpu)
    if hasattr(array, '__dlpack__'):
        try:
            return np.from_dlpack(array)
        except (TypeError, BufferError):
            pass
    return np.asarray(array)

def _iter(self, flag=True, filter_passthrough=True):
    """
        Generate (idx, (name, trans)) tuples from self.steps

        When filter_passthrough is True, 'passthrough' and None transformers
        are filtered out.
        """
    stop = len(self.steps)
    if not flag:
        stop -= 1
    for idx, (name, trans) in enumerate(islice(self.steps, 0, stop)):
        if not filter_passthrough:
            yield (idx, name, trans)
        elif trans is not None and trans != 'passthrough':
            yield (idx, name, trans)

def _safe_min(items):
    """Compute the minimum of a list of potentially non-comparable values.

    If values cannot be directly compared due to type incompatibility, the object with
    the lowest string representation is returned.
    """
    try:
        return min(items)
    except TypeError as e:
        if "'<' not supported between" in str(e):
            return min(items, key=lambda x: (str(type(x)), str(x)))
        raise

def _fit_single_estimator(estimator, X, y, fit_params, message_clsname=None, message=None):
    """Private function used to fit an estimator within a job."""
    if not _routing_enabled() and 'sample_weight' in fit_params:
        try:
            with _print_elapsed_time(message_clsname, message):
                estimator.fit(X, y, sample_weight=fit_params['sample_weight'])
        except TypeError as exc:
            if "unexpected keyword argument 'sample_weight'" in str(exc):
                raise TypeError('Underlying estimator {} does not support sample weights.'.format(estimator.__class__.__name__)) from exc
            raise
    else:
        with _print_elapsed_time(message_clsname, message):
            estimator.fit(X, y, **fit_params)
    return estimator

@property
def column_arrays(self) -> list[np.ndarray]:
    """
        Used in the JSON C code to access column arrays.
        This optimizes compared to using `iget_values` by converting each

        Warning! This doesn't handle Copy-on-Write, so should be used with
        caution (current use case of consuming this in the JSON code is fine).
        """
    result: list[np.ndarray | None] = [None] * len(self.items)
    for blk in self.blocks:
        mgr_locs = blk._mgr_locs
        values = blk.array_values._values_for_json()
        if values.ndim == 1:
            result[mgr_locs[0]] = values
        else:
            for i, loc in enumerate(mgr_locs):
                result[loc] = values[i]
    return result

def _get_scorer(self):
    """Make sure the scorer is weighted if necessary.

        This uses `self._get_scorer_instance()` implemented in child objects to get the
        raw scorer instance of the estimator, which will be ignored if `self.scoring` is
        not None.
        """
    if _routing_enabled() and self.scoring is None:
        return self._get_scorer_instance().set_score_request(sample_weight=True)
    return check_scoring(estimator=self, scoring=self.scoring, allow_none=True)

def add_url_rule(self, rule: str, endpoint: str | None=None, view_func: ft.RouteCallable | None=None, **options: t.Any) -> None:
    """A helper method to register a rule (and optionally a view function)
        to the application.  The endpoint is automatically prefixed with the
        blueprint's name.
        """
    if self.url_prefix is not None:
        if rule:
            rule = '/'.join((self.url_prefix.rstrip('/'), rule.lstrip('/')))
        else:
            rule = self.url_prefix
    options.setdefault('subdomain', self.subdomain)
    if endpoint is None:
        endpoint = _endpoint_from_view_func(view_func)
    defaults = self.url_defaults
    if 'defaults' in options:
        defaults = dict(defaults, **options.pop('defaults'))
    self.app.add_url_rule(rule, f'{self.name_prefix}.{self.name}.{endpoint}'.lstrip('.'), view_func, defaults=defaults, **options)

def _get_result_dtype(self, dtype: np.dtype) -> np.dtype:
    """
        Get the desired dtype of a result based on the
        input dtype and how it was computed.

        Parameters
        ----------
        dtype : np.dtype

        Returns
        -------
        np.dtype
            The desired dtype of the result.
        """
    how = self.how
    if how in ['sum', 'cumsum', 'sum', 'prod', 'cumprod']:
        if dtype == np.dtype(bool):
            return np.dtype(np.int64)
    elif how in ['mean', 'median', 'var', 'std', 'sem']:
        if dtype.kind in 'fc':
            return dtype
        elif dtype.kind in 'iub':
            return np.dtype(np.float64)
    return dtype

def preprocess_request(self, ctx: AppContext) -> ft.ResponseReturnValue | None:
    """Called before the request is dispatched. Calls
        :attr:`url_value_preprocessors` registered with the app and the
        current blueprint (if any). Then calls :attr:`before_request_funcs`
        registered with the app and the blueprint.

        If any :meth:`before_request` handler returns a non-None value, the
        value is handled as if it was the return value from the view, and
        further request handling is stopped.
        """
    req = ctx.request
    names = (None, *reversed(req.blueprints))
    for name in names:
        if name in self.url_value_preprocessors:
            for url_func in self.url_value_preprocessors[name]:
                url_func(req.endpoint, req.view_args)
    for name in names:
        if name in self.before_request_funcs:
            for before_func in self.before_request_funcs[name]:
                rv = self.ensure_sync(before_func)()
                if rv is not None:
                    return rv
    return None

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    """
        Fit the OrdinalEncoder to X.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
            The data to determine the categories of each feature.

        y : None
            Ignored. This parameter exists only for compatibility with
            :class:`~sklearn.pipeline.Pipeline`.

        Returns
        -------
        self : object
            Fitted encoder.
        """
    if self.handle_unknown == 'use_encoded_value':
        if is_scalar_nan(self.unknown_value):
            if np.dtype(self.dtype).kind != 'f':
                raise ValueError(f'When unknown_value is np.nan, the dtype parameter should be a float dtype. Got {self.dtype}.')
        elif not isinstance(self.unknown_value, numbers.Integral):
            raise TypeError(f"unknown_value should be an integer or np.nan when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    elif self.unknown_value is not None:
        raise TypeError(f"unknown_value should only be set when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    fit_results = self._fit(X, handle_unknown=self.handle_unknown, ensure_all_finite='allow-nan', return_and_ignore_missing_for_infrequent=True)
    self._missing_indices = fit_results['missing_indices']
    cardinalities = [len(categories) for categories in self.categories_]
    if self._infrequent_enabled:
        for feature_idx, infrequent in enumerate(self.infrequent_categories_):
            if infrequent is not None:
                cardinalities[feature_idx] -= len(infrequent)
    for cat_idx, categories_for_idx in enumerate(self.categories_):
        if is_scalar_nan(categories_for_idx[-1]):
            cardinalities[cat_idx] -= 1
    if self.handle_unknown == 'use_encoded_value':
        for cardinality in cardinalities:
            if 0 <= self.unknown_value < cardinality:
                raise ValueError(f'The used value for unknown_value {self.unknown_value} is one of the values already used for encoding the seen categories.')
    if self._missing_indices:
        if np.dtype(self.dtype).kind != 'f' and is_scalar_nan(self.encoded_missing_value):
            raise ValueError(f'There are missing values in features {list(self._missing_indices)}. For OrdinalEncoder to encode missing values with dtype: {self.dtype}, set encoded_missing_value to a non-nan value, or set dtype to a float')
        if not is_scalar_nan(self.encoded_missing_value):
            invalid_features = [cat_idx for cat_idx, cardinality in enumerate(cardinalities) if cat_idx in self._missing_indices and 0 <= self.encoded_missing_value < cardinality]
            if invalid_features:
                if hasattr(self, 'feature_names_in_'):
                    invalid_features = self.feature_names_in_[invalid_features]
                raise ValueError(f'encoded_missing_value ({self.encoded_missing_value}) is already used to encode a known category in features: {invalid_features}')
    return self

def _maybe_unbox_datetimelike(value: Scalar, dtype: DtypeObj) -> Scalar:
    """
    Convert a Timedelta or Timestamp to timedelta64 or datetime64 for setting
    into a numpy array.  Failing to unbox would risk dropping nanoseconds.

    Notes
    -----
    Caller is responsible for checking dtype.kind in "mM"
    """
    if is_valid_na_for_dtype(value, dtype):
        value = dtype.type('NaT', 'ns')
    elif isinstance(value, Timestamp):
        if value.tz is None:
            value = value.to_datetime64()
        elif not isinstance(dtype, DatetimeTZDtype):
            raise TypeError('Cannot unbox tzaware Timestamp to tznaive dtype')
    elif isinstance(value, Timedelta):
        value = value.to_timedelta64()
    _disallow_mismatched_datetimelike(value, dtype)
    return value

def get_descendants(self, file_path):
    """Return the descendants from this task along the given path."""
    if len(file_path) == 1:
        return [self]
    if file_path[1] not in self.children:
        return [self, None]
    return [self] + self.children[file_path[1]].get_descendants(file_path[1:])

@final
def _set_noconvert_dtype_columns(self, col_indices: list[int], names: Sequence[Hashable]) -> set[int]:
    """
        Set the columns that should not undergo dtype conversions.

        Currently, any column that is involved with date parsing will not
        undergo such conversions. If usecols is specified, the positions of the columns
        not to cast is relative to the usecols not to all columns.

        Parameters
        ----------
        col_indices: The indices specifying order and positions of the columns
        names: The column names which order is corresponding with the order
               of col_indices

        Returns
        -------
        A set of integers containing the positions of the columns not to convert.
        """
    usecols: list[int] | list[str] | None
    noconvert_columns = set()
    if self.usecols_dtype == 'integer':
        usecols = sorted(self.usecols)
    elif callable(self.usecols) or self.usecols_dtype not in ('empty', None):
        usecols = col_indices
    else:
        usecols = None

    def _set(x) -> int:
        if usecols is not None and is_integer(x):
            x = usecols[x]
        if not is_integer(x):
            x = col_indices[names.index(x)]
        return None
    if isinstance(self.parse_dates, list):
        validate_parse_dates_presence(self.parse_dates, names)
        for val in self.parse_dates:
            noconvert_columns.add(_set(val))
    elif self.parse_dates:
        if isinstance(self.index_col, list):
            for k in self.index_col:
                noconvert_columns.add(_set(k))
        elif self.index_col is not None:
            noconvert_columns.add(_set(self.index_col))
    return noconvert_columns

def select_describe_func(data: Series) -> Callable:
    """Select proper function for describing series based on data type.

    Parameters
    ----------
    data : Series
        Series to be described.
    """
    if is_bool_dtype(data.dtype):
        return not describe_categorical_1d
    elif is_numeric_dtype(data):
        return describe_numeric_1d
    elif data.dtype.kind == 'M' or isinstance(data.dtype, DatetimeTZDtype):
        return describe_timestamp_1d
    elif data.dtype.kind == 'm':
        return describe_numeric_1d
    else:
        return describe_categorical_1d

def is_polars_df(X):
    """Return True if the X is a polars dataframe.

    Parameters
    ----------
    X : {array-like, dataframe}
        The array-like or dataframe object to check.

    Returns
    -------
    bool
        True if the X is a polarsdataframe, False otherwise.
    """
    try:
        pl = sys.modules['polars']
    except KeyError:
        return False
    return isinstance(X, pl.DataFrame)

def _inclusive_low_high(target):
    """Generate values low and high to be within the interval range.

    This is used in tests only.

    Returns
    -------
    low, high : tuple of floats
        The returned values low and high lie within the interval.
    """
    eps = 10 * ulp(1)
    if target.low == -float('inf'):
        low = -10000000000.0
    elif target.low < 0:
        low = target.low * (1 - eps) + eps
    else:
        low = target.low * (1 + eps) + eps
    if target.high == float('inf'):
        high = 10000000000.0
    elif target.high < 0:
        high = target.high * (1 + eps) - eps
    else:
        high = target.high * (1 - eps) - eps
    return (float(low), float(high))

def fit_intercept_only(self, y_true, sample_weight=None):
    """Compute raw_prediction of an intercept-only model.

        This is the weighted median of the target, i.e. over the samples
        axis=0.
        """
    if sample_weight is None:
        return np.percentile(y_true, 100 * self.closs.quantile, axis=0)
    else:
        return _weighted_percentile(y_true, sample_weight, 100 * self.closs.quantile)

def _prepare_categoricals(self, data: DataFrame) -> DataFrame:
    """
        Check for categorical columns, retain categorical information for
        Stata file and convert categorical data to int
        """
    is_cat = [isinstance(dtype, CategoricalDtype) for dtype in data.dtypes]
    if not any(is_cat):
        return data
    self._has_value_labels |= np.array(is_cat)
    get_base_missing_value = StataMissingValue.get_base_missing_value
    data_formatted = []
    for col, col_is_cat in zip(data, is_cat, strict=True):
        if col_is_cat:
            svl = StataValueLabel(data[col], encoding=self._encoding)
            self._value_labels.append(svl)
            dtype = data[col].cat.codes.dtype
            if dtype == np.int64:
                raise ValueError('It is not possible to export int64-based categorical data to Stata.')
            values = data[col].cat.codes._values.copy()
            if values.max() >= get_base_missing_value(dtype):
                if dtype == np.int8:
                    dtype = np.dtype(np.int16)
                elif dtype == np.int16:
                    dtype = np.dtype(np.int32)
                else:
                    dtype = np.dtype(np.float64)
                values = np.array(values, dtype=dtype)
            values[values == -1] = get_base_missing_value(dtype)
            data_formatted.append((col, values))
        else:
            data_formatted.append((col, data[col]))
    return DataFrame.from_dict(dict(data_formatted))

@classmethod
def _if_else(cls, cond: npt.NDArray[np.bool_] | bool, left: ArrayLike | Scalar, right: ArrayLike | Scalar) -> pa.Array:
    """
        Choose values based on a condition.

        Analogous to pyarrow.compute.if_else, with logic
        to fallback to numpy for unsupported types.

        Parameters
        ----------
        cond : npt.NDArray[np.bool_] or bool
        left : ArrayLike | Scalar
        right : ArrayLike | Scalar

        Returns
        -------
        pa.Array
        """

    def _maybe_combine(arr):
        if not isinstance(arr, pa.ChunkedArray) or not (pa.types.is_string(arr.type) or pa.types.is_large_string(arr.type)):
            return arr
        if not any((c.offset != 0 for c in arr.chunks)):
            return arr
        try:
            return arr.combine_chunks()
        except (pa.ArrowInvalid, pa.ArrowCapacityError, MemoryError):
            return None
    left_c, right_c = (_maybe_combine(left), _maybe_combine(right))
    if left_c is not None and right_c is not None:
        try:
            return pc.if_else(cond, left_c, right_c)
        except pa.ArrowNotImplementedError:
            pass
    if left_c is not None:
        left = left_c
    if right_c is not None:
        right = right_c

    def _to_numpy_and_type(value) -> tuple[np.ndarray, pa.DataType | None]:
        if isinstance(value, (pa.Array, pa.ChunkedArray)):
            pa_type = value.type
        elif isinstance(value, pa.Scalar):
            pa_type = value.type
            value = value.as_py()
        else:
            pa_type = None
        return (np.array(value, dtype=object), pa_type)
    left, left_type = _to_numpy_and_type(left)
    right, right_type = _to_numpy_and_type(right)
    pa_type = left_type or right_type
    result = np.where(cond, left, right)
    return pa.array(result, type=pa_type, from_pandas=is_nan_na())

def _handle_usecols(self, columns: list[list[Scalar | None]], usecols_key: list[Scalar | None], num_original_columns: int) -> list[list[Scalar | None]]:
    """
        Sets self._col_indices

        usecols_key is used if there are string usecols.
        """
    col_indices: set[int] | list[int]
    if self.usecols is not None:
        if callable(self.usecols):
            col_indices = evaluate_callable_usecols(self.usecols, usecols_key)
        elif any((isinstance(u, str) for u in self.usecols)):
            if len(columns) > 1:
                raise ValueError('If using multiple headers, usecols must be integers.')
            col_indices = []
            for col in self.usecols:
                if isinstance(col, str):
                    try:
                        col_indices.append(usecols_key.index(col))
                    except ValueError:
                        self._validate_usecols_names(self.usecols, usecols_key)
                else:
                    col_indices.append(col)
        else:
            missing_usecols = [col for col in self.usecols if col >= num_original_columns]
            if missing_usecols:
                raise ParserError(f'Defining usecols with out-of-bounds indices is not allowed. {missing_usecols} are out-of-bounds.')
            col_indices = self.usecols
        columns = [[n for i, n in enumerate(column) if i in col_indices] for column in columns]
        self._col_indices = sorted(col_indices)
    return columns

def is_fsspec_url(field: FilePath | BaseBuffer) -> bool:
    """
    Returns true if the given URL looks like
    something fsspec can handle
    """
    return isinstance(field, str) and bool(_FSSPEC_URL_PATTERN.match(field)) and (not field.startswith(('http://', 'https://')))

def analyzeline(session, case, line):
    """
    Reads each line in the input file in sequence and updates global vars.

    Effectively reads and collects information from the input file to the
    global variable groupcache, a dictionary containing info about each part
    of the fortran module.

    At the end of analyzeline, information is filtered into the correct dict
    keys, but parameter values and dimensions are not yet interpreted.
    """
    global groupcounter, groupname, groupcache, grouplist, filepositiontext
    global currentfilename, f77modulename, neededinterface, neededmodule
    global expectbegin, gotnextfile, previous_context
    block = session.group('this')
    if case != 'multiline':
        previous_context = None
    if expectbegin and case not in ['begin', 'call', 'callfun', 'type'] and (not skipemptyends) and (groupcounter < 1):
        newname = os.path.basename(currentfilename).split('.')[0]
