def _is_floats_color(token: Color | Collection[Color]) -> bool:
    """Check if color comprises a sequence of floats representing color."""
    return bool(is_list_like(token) and (len(token) == 3 or len(token) == 4) and all((isinstance(x, (int, float)) for x in token)))

def dtypes(self, *, device=None, kind=None):
    """
        The array API data types supported by CuPy.

        Note that this function only returns data types that are defined by
        the array API.

        Parameters
        ----------
        device : str, optional
            The device to get the data types for.
        kind : str or tuple of str, optional
            The kind of data types to return. If ``None``, all data types are
            returned. If a string, only data types of that kind are returned.
            If a tuple, a dictionary containing the union of the given kinds
            is returned. The following kinds are supported:

            - ``'bool'``: boolean data types (i.e., ``bool``).
            - ``'signed integer'``: signed integer data types (i.e., ``int8``,
              ``int16``, ``int32``, ``int64``).
            - ``'unsigned integer'``: unsigned integer data types (i.e.,
              ``uint8``, ``uint16``, ``uint32``, ``uint64``).
            - ``'integral'``: integer data types. Shorthand for ``('signed
              integer', 'unsigned integer')``.
            - ``'real floating'``: real-valued floating-point data types
              (i.e., ``float32``, ``float64``).
            - ``'complex floating'``: complex floating-point data types (i.e.,
              ``complex64``, ``complex128``).
            - ``'numeric'``: numeric data types. Shorthand for ``('integral',
              'real floating', 'complex floating')``.

        Returns
        -------
        dtypes : dict
            A dictionary mapping the names of data types to the corresponding
            CuPy data types.

        See Also
        --------
        __array_namespace_info__.capabilities,
        __array_namespace_info__.default_device,
        __array_namespace_info__.default_dtypes,
        __array_namespace_info__.devices

        Examples
        --------
        >>> info = xp.__array_namespace_info__()
        >>> info.dtypes(kind='signed integer')
        {'int8': cupy.int8,
         'int16': cupy.int16,
         'int32': cupy.int32,
         'int64': cupy.int64}

        """
    if kind is None:
        return {'bool': dtype(bool), 'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'bool':
        return {'bool': bool}
    if kind == 'signed integer':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64)}
    if kind == 'unsigned integer':
        return {'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'integral':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'real floating':
        return {'float32': dtype(float32), 'float64': dtype(float64)}
    if kind == 'complex floating':
        return {'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'numeric':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if isinstance(kind, tuple):
        res = {}
        for k in kind:
            res.update(self.dtypes(kind=k))
        return res
    raise ValueError(f'unsupported kind: {kind!r}')

def maybe_downcast_to_dtype(result: ArrayLike, dtype: np.dtype) -> ArrayLike:
    """
    try to cast to the specified dtype (e.g. convert back to bool/int
    or could be an astype of float64->float32
    """
    if isinstance(result, ABCSeries):
        result = result._values
    do_round = False
    if not isinstance(dtype, np.dtype):
        raise TypeError(dtype)
    converted = maybe_downcast_numeric(result, dtype, do_round)
    if converted is not result:
        return converted
    if dtype.kind in 'mM' and result.dtype.kind in 'if':
        result = result.astype(dtype)
    elif dtype.kind == 'm' and result.dtype == _dtype_obj:
        result = cast('np.ndarray', result)
        result = array_to_timedelta64(result)
    elif dtype == np.dtype('M8[ns]') and result.dtype == _dtype_obj:
        result = cast('np.ndarray', result)
        return np.asarray(maybe_cast_to_datetime(result, dtype=dtype))
    return result

