def read_column(self, column: str, where=None, start: int | None=None, stop: int | None=None):
    """
        return a single column from the table, generally only indexables
        are interesting
        """
    if not self.infer_axes():
        return False
    if where is not None:
        raise TypeError('read_column does not currently accept a where clause')
    for a in self.axes:
        if column == a.name:
            if not a.is_data_indexable:
                raise ValueError(f'column [{column}] can not be extracted individually; it is not data indexable')
            c = getattr(self.table.cols, column)
            a.set_info(self.info)
            col_values = a.convert(c[start:stop], nan_rep=self.nan_rep, encoding=self.encoding, errors=self.errors)
            cvs = col_values[1]
            dtype = getattr(self.table.attrs, f'{column}_meta', None)
            return Series(cvs, name=column, copy=False, dtype=dtype)
    raise KeyError(f'column [{column}] not found in the table')

def _minmax(func: Callable, values: np.ndarray, mask: npt.NDArray[np.bool_], *, skipna: bool=True, axis: AxisInt | None=None):
    """
    Reduction for 1D masked array.

    Parameters
    ----------
    func : np.min or np.max
    values : np.ndarray
        Numpy array with the values (can be of any dtype that support the
        operation).
    mask : np.ndarray[bool]
        Boolean numpy array (True values indicate missing values).
    skipna : bool, default True
        Whether to skip NA.
    axis : int, optional, default None
    """
    if not skipna:
        if axis is not None and values.ndim > 1:
            return func(values, axis=axis)
        if mask.any() or not values.size:
            return libmissing.NA
        else:
            return func(values, axis=axis)
    else:
        if axis is not None and values.ndim > 1:
            if func is np.min:
                fill_value = _get_max_value(values.dtype)
            else:
                fill_value = _get_min_value(values.dtype)
            filled = np.where(mask, fill_value, values)
            return func(filled, axis=axis)
        subset = values[~mask]
        if subset.size:
            return func(subset, axis=axis)
        else:
            return libmissing.NA

def apply_compat(self):
    """compat apply method for funcs in listlikes and dictlikes.

         Used for each callable when giving listlikes and dictlikes of callables to
         apply. Needed for compatibility with Pandas < v2.1.

        .. versionadded:: 2.1.0
        """
    obj = self.obj
    func = self.func
    if callable(func):
        f = com.get_cython_func(func)
        if f and (not self.args) and (not self.kwargs):
            return obj.apply(func, by_row=False)
    try:
        result = obj.apply(func, by_row='compat')
    except (ValueError, AttributeError, TypeError):
        result = obj.apply(func, by_row=False)
    return result

def _from_ctypes_scalar(t):
    """
    Return the dtype type with endianness included if it's the case
    """
    if getattr(t, '__ctype_be__', None) is t:
        return None
    elif getattr(t, '__ctype_le__', None) is t:
        return np.dtype('<' + t._type_)
    else:
        return np.dtype(t._type_)

@staticmethod
def _get_base_knot_positions(X, n_knots=10, knots='uniform', sample_weight=None):
    """Calculate base knot positions for `knots` either "uniform" or "quantile".

        Base knots such that first knot <= feature <= last knot. For the
        B-spline construction with scipy.interpolate.BSpline, 2*degree knots
        beyond the base interval are added.

        Returns
        -------
        knots : ndarray of shape (n_knots, n_features), dtype=np.float64
            Knot positions (points) of base interval.
        """
    if knots == 'quantile':
        percentile_ranks = 100 * np.linspace(start=0, stop=1, num=n_knots, dtype=np.float64)
        if sample_weight is None:
            knots = np.nanpercentile(X, percentile_ranks, axis=0)
        else:
            knots = _weighted_percentile(X, sample_weight, percentile_ranks).T
    else:
        mask = slice(None, None, 1) if sample_weight is None else sample_weight > 0
        x_min = np.zeros(X.shape[1], dtype=np.float64)
        x_max = np.zeros(X.shape[1], dtype=np.float64)
        for feature_idx in range(X.shape[1]):
            x = X[mask, feature_idx]
            if np.all(np.isnan(x)):
                continue
            else:
                x_min[feature_idx] = np.nanmin(x)
                x_max[feature_idx] = np.nanmax(x)
        knots = np.linspace(start=x_min, stop=x_max, num=n_knots, endpoint=True, dtype=np.float64)
    return knots

def safe_sort_index(index: Index) -> Index:
    """
    Returns the sorted index

    We keep the dtypes and the name attributes.

    Parameters
    ----------
    index : an Index

    Returns
    -------
    Index
    """
    if index.is_monotonic_increasing:
        return index
    try:
        array_sorted = safe_sort(index)
    except TypeError:
        pass
    else:
        if isinstance(array_sorted, Index):
            return array_sorted
        array_sorted = cast('np.ndarray', array_sorted)
        if isinstance(index, MultiIndex):
            index = MultiIndex.from_tuples(array_sorted, names=index.names)
        else:
            index = Index(array_sorted, name=index.name, dtype=index.dtype)
    return index

def readfortrancode(ffile, dowithline=show, istop=1):
    """
    Read fortran codes from files and
     1) Get rid of comments, line continuations, and empty lines; lower cases.
     2) Call dowithline(line) on every line.
     3) Recursively call itself when statement "include '<filename>'" is met.
    """
    global gotnextfile, filepositiontext, currentfilename, sourcecodeform, strictf77
    global beginpattern, quiet, verbose, dolowercase, include_paths
    if not istop:
        saveglobals = (gotnextfile, filepositiontext, currentfilename, sourcecodeform, strictf77, beginpattern, quiet, verbose, dolowercase)
    if ffile == []:
        return
    localdolowercase = dolowercase
    cont = False
    finalline = ''
    ll = ''
    includeline = re.compile('\\s*include\\s*(\\\'|")(?P<name>[^\\\'"]*)(\\\'|")', re.I)
    cont1 = re.compile('(?P<line>.*)&\\s*\\Z')
    cont2 = re.compile('(\\s*&|)(?P<line>.*)')
    mline_mark = re.compile(".*?'''")
    if istop:
        dowithline('', -1)
    ll, l1 = ('', '')
    spacedigits = [' '] + [str(_m) for _m in range(10)]
    filepositiontext = ''
    fin = fileinput.FileInput(ffile, openhook=openhook)
    while True:
        try:
            l = fin.readline()
        except UnicodeDecodeError as msg:
            raise Exception(f'readfortrancode: reading {fin.filename()}#{fin.lineno()} failed with\n{msg}.\nIt is likely that installing charset_normalizer package will help f2py determine the input file encoding correctly.')
        if not l:
            break
        if fin.isfirstline():
            filepositiontext = ''
            currentfilename = fin.filename()
            gotnextfile = 1
            l1 = l
            strictf77 = 0
            sourcecodeform = 'fix'
            ext = os.path.splitext(currentfilename)[1]
            if Path(currentfilename).suffix.lower() in COMMON_FIXED_EXTENSIONS and (not (_has_f90_header(l) or _has_fix_header(l))):
                strictf77 = 1
            elif is_free_format(currentfilename) and (not _has_fix_header(l)):
                sourcecodeform = 'free'
            if strictf77:
                beginpattern = beginpattern77
            else:
                beginpattern = beginpattern90
            outmess(f"\tReading file {currentfilename!r} (format:{sourcecodeform}{(',strict' if strictf77 else '')})\n")
        l = l.expandtabs().replace('\xa0', ' ')
        while not l == '':
            if l[-1] not in '\n\r\x0c':
                break
            l = l[:-1]
        is_f2py_directive = False
        l, rl = split_by_unquoted(l, '!')
        l += ' '
        if rl[:5].lower() == '!f2py':
            l, _ = split_by_unquoted(l + 4 * ' ' + rl[5:], '!')
            is_f2py_directive = True
        if l.strip() == '':
            if sourcecodeform == 'free':
                pass
            else:
                cont = False
            continue
        if sourcecodeform == 'fix':
            if l[0] in ['*', 'c', '!', 'C', '#']:
                if l[1:5].lower() == 'f2py':
                    l = '     ' + l[5:]
                    is_f2py_directive = True
                else:
                    cont = False
                    is_f2py_directive = False
                    continue
            elif strictf77:
                if len(l) > 72:
                    l = l[:72]
            if l[0] not in spacedigits:
                raise Exception(f'readfortrancode: Found non-(space,digit) char in the first column.\n\tAre you sure that this code is in fix form?\n\tline={l!r}')
            if (not cont or strictf77) and (len(l) > 5 and (not l[5] == ' ')):
                ll = ll + l[6:]
                finalline = ''
                origfinalline = ''
            else:
                r = cont1.match(l)
                if r:
                    l = r.group('line')
                if cont:
                    ll = ll + cont2.match(l).group('line')
                    finalline = ''
                    origfinalline = ''
                else:
                    l = '     ' + l[5:]
                    if localdolowercase:
                        finalline = ll.lower()
                    else:
                        finalline = ll
                    origfinalline = ll
                    ll = l
        elif sourcecodeform == 'free':
            if not cont and ext == '.pyf' and mline_mark.match(l):
                l = l + '\n'
                while True:
                    lc = fin.readline()
                    if not lc:
                        errmess('Unexpected end of file when reading multiline\n')
                        break
                    l = l + lc
                    if mline_mark.match(lc):
                        break
                l = l.rstrip()
            r = cont1.match(l)
            if r:
                l = r.group('line')
            if cont:
                ll = ll + cont2.match(l).group('line')
                finalline = ''
                origfinalline = ''
            else:
                if localdolowercase:
                    finalline = ll.lower() if not (is_f2py_directive and iscstyledirective(ll)) else ll
                else:
                    finalline = ll
                origfinalline = ll
                ll = l
            cont = r is not None
        else:
            raise ValueError(f"Flag sourcecodeform must be either 'fix' or 'free': {repr(sourcecodeform)}")
        filepositiontext = f'Line #{fin.filelineno() - 1} in {currentfilename}:"{l1}"\n\t'
        m = includeline.match(origfinalline)
        if m:
            fn = m.group('name')
            if os.path.isfile(fn):
                readfortrancode(fn, dowithline=dowithline, istop=0)
            else:
                include_dirs = [os.path.dirname(currentfilename)] + include_paths
                foundfile = 0
                for inc_dir in include_dirs:
                    fn1 = os.path.join(inc_dir, fn)
                    if os.path.isfile(fn1):
                        foundfile = 1
                        readfortrancode(fn1, dowithline=dowithline, istop=0)
                        break
                if not foundfile:
                    outmess(f'readfortrancode: could not find include file {fn!r} in {os.pathsep.join(include_dirs)}. Ignoring.\n')
        else:
            dowithline(finalline)
        l1 = ll
    if localdolowercase:
        finalline = ll.lower()
    else:
        finalline = ll
    origfinalline = ll
    filepositiontext = f'Line #{fin.filelineno() - 1} in {currentfilename}:"{l1}"\n\t'
    m = includeline.match(origfinalline)
    if m:
        fn = m.group('name')
        if os.path.isfile(fn):
            readfortrancode(fn, dowithline=dowithline, istop=0)
        else:
            include_dirs = [os.path.dirname(currentfilename)] + include_paths
            foundfile = 0
            for inc_dir in include_dirs:
                fn1 = os.path.join(inc_dir, fn)
                if os.path.isfile(fn1):
                    foundfile = 1
                    readfortrancode(fn1, dowithline=dowithline, istop=0)
                    break
            if not foundfile:
                outmess(f'readfortrancode: could not find include file {fn!r} in {os.pathsep.join(include_dirs)}. Ignoring.\n')
    else:
        dowithline(finalline)
    filepositiontext = ''
    fin.close()
    if istop:
        dowithline('', 1)
    else:
        gotnextfile, filepositiontext, currentfilename, sourcecodeform, strictf77, beginpattern, quiet, verbose, dolowercase = saveglobals

def _check_targets(y_true, y_pred, sample_weight=None):
    """Check that y_true and y_pred belong to the same classification task.

    This converts multiclass or binary types to a common shape, and raises a
    ValueError for:

        - targets of different lengths,
        - a mix of multilabel and multiclass targets,
        - a mix of multilabel target and anything else
          (because there are no explicit labels),
        - the presence of continuous-valued or multioutput (or 'unknown') targets,
        - mix of string and integer labels.

    Column vectors are squeezed to 1d, while multilabel formats are returned
    as CSR sparse label indicators.

    Parameters
    ----------
    y_true : array-like

    y_pred : array-like

    sample_weight : array-like, default=None

    Returns
    -------
    type_true : one of {'multilabel-indicator', 'multiclass', 'binary'}
        The type of the true target data, as output by
        ``utils.multiclass.type_of_target``.

    unique_labels : array
        An ordered array of unique labels occurring either in `y_true`, `y_pred` or
        both.

    y_true : array or indicator matrix

    y_pred : array or indicator matrix

    sample_weight : array or None
    """
    xp, _ = get_namespace(y_true, y_pred, sample_weight)
    check_consistent_length(y_true, y_pred, sample_weight)
    type_true = type_of_target(y_true, input_name='y_true')
    type_pred = type_of_target(y_pred, input_name='y_pred')
    for array in [y_true, y_pred]:
        if _num_samples(array) < 1:
            raise ValueError('Found empty input array (e.g., `y_true` or `y_pred`) while a minimum of 1 sample is required.')
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, y_true, force_float_dtype=False)
    y_type = {type_true, type_pred}
    if y_type == {'binary', 'multiclass'}:
        y_type = {'multiclass'}
    if len(y_type) > 1:
        raise ValueError("Classification metrics can't handle a mix of {0} and {1} targets".format(type_true, type_pred))
    y_type = y_type.pop()
    if y_type not in ['binary', 'multiclass', 'multilabel-indicator']:
        raise ValueError('{0} is not supported'.format(y_type))
    if y_type in ['binary', 'multiclass']:
        try:
            y_true = column_or_1d(y_true, input_name='y_true')
            y_pred = column_or_1d(y_pred, input_name='y_pred')
        except TypeError as e:
            if 'Sparse data was passed' in str(e):
                raise TypeError('Sparse input is only supported when targets are of multilabel type') from e
            else:
                raise
    unique_labels_ = unique_labels(y_true, y_pred, ys_types={y_type})
    if y_type == 'binary':
        if unique_labels_.shape[0] > 2:
            y_type = 'multiclass'
    xp, _ = get_namespace(y_true, y_pred)
    if y_type.startswith('multilabel'):
        if _is_numpy_namespace(xp):
            y_true = _align_api_if_sparse(csr_array(y_true))
            y_pred = _align_api_if_sparse(csr_array(y_pred))
        y_type = 'multilabel-indicator'
    return (y_type, unique_labels_, y_true, y_pred, sample_weight)

def iter_lines(self, chunk_size: int=ITER_CHUNK_SIZE, decode_unicode: bool=False, delimiter: str | bytes | None=None) -> Iterator[str | bytes]:
    """Iterates over the response data, one line at a time.  When
        stream=True is set on the request, this avoids reading the
        content at once into memory for large responses.

        The decode_unicode param works the same as in `iter_content`, with the
        same caveats.

        .. note:: This method is not reentrant safe.
        """
    pending: str | bytes | None = None
    for chunk in self.iter_content(chunk_size=chunk_size, decode_unicode=decode_unicode):
        if pending is not None:
            chunk = cast('str | bytes', pending + chunk)
        if delimiter:
            lines = chunk.split(delimiter)
        else:
            lines = chunk.splitlines()
        if lines and lines[-1] and chunk and (lines[-1][-1] == chunk[-1]):
            pending = lines.pop()
        else:
            pending = None
        yield from lines
    if pending is not None:
        yield pending

@classmethod
def _box_pa(cls, value, pa_type: pa.DataType | None=None) -> pa.Array | pa.ChunkedArray | pa.Scalar:
    """
        Box value into a pyarrow Array, ChunkedArray or Scalar.

        Parameters
        ----------
        value : any
        pa_type : pa.DataType | None

        Returns
        -------
        pa.Array or pa.ChunkedArray or pa.Scalar
        """
    if isinstance(value, pa.Scalar) or not is_list_like(value):
        return cls._box_pa_scalar(value, pa_type)
    return cls._box_pa_array(value, pa_type)

def _formatter_func(self, tup) -> tuple[str, ...]:
    """
        Formats each item in tup according to its level's formatter function.
        """
    return tuple((level._formatter_func(val) for level, val in zip(self.levels, tup, strict=True)))

@final
def _infer_types(self, values, na_values, no_dtype_specified, try_num_bool: bool=True) -> tuple[ArrayLike, int]:
    """
        Infer types of values, possibly casting

        Parameters
        ----------
        values : ndarray
        na_values : set
        no_dtype_specified: Specifies if we want to cast explicitly
        try_num_bool : bool, default try
           try to cast values to numeric (first preference) or boolean

        Returns
        -------
        converted : ndarray or ExtensionArray
        na_count : int
        """
    na_count = 0
    if issubclass(values.dtype.type, (np.number, np.bool_)):
        na_values = np.array([val for val in na_values if not isinstance(val, str)])
        mask = algorithms.isin(values, na_values)
        na_count = mask.astype('uint8', copy=False).sum()
        if na_count > 0:
            if is_integer_dtype(values):
                values = values.astype(np.float64)
            np.putmask(values, mask, np.nan)
        return (values, na_count)
    dtype_backend = self.dtype_backend
    non_default_dtype_backend = no_dtype_specified and dtype_backend is not lib.no_default
    result: ArrayLike
    if try_num_bool and is_object_dtype(values.dtype):
        try:
            result, result_mask = lib.maybe_convert_numeric(values, na_values, False, convert_to_masked_nullable=non_default_dtype_backend)
        except (ValueError, TypeError):
            na_count = parsers.sanitize_objects(values, na_values)
            result = values
        else:
            if non_default_dtype_backend:
                if result_mask is None:
                    result_mask = np.zeros(result.shape, dtype=np.bool_)
                if result_mask.all():
                    result = IntegerArray(np.ones(result_mask.shape, dtype=np.int64), result_mask)
                elif is_integer_dtype(result):
                    result = IntegerArray(result, result_mask)
                elif is_bool_dtype(result):
                    result = BooleanArray(result, result_mask)
                elif is_float_dtype(result):
                    result = FloatingArray(result, result_mask)
                na_count = result_mask.sum()
            else:
                na_count = isna(result).sum()
    else:
        result = values
        if values.dtype == np.object_:
            na_count = parsers.sanitize_objects(values, na_values)
    if result.dtype == np.object_ and try_num_bool and (len(result) == 0 or not isinstance(result[0], int)):
        result, bool_mask = libops.maybe_convert_bool(np.asarray(values), true_values=self.true_values, false_values=self.false_values, convert_to_masked_nullable=non_default_dtype_backend)
        if result.dtype == np.bool_ and non_default_dtype_backend:
            if bool_mask is None:
                bool_mask = np.zeros(result.shape, dtype=np.bool_)
            result = BooleanArray(result, bool_mask)
        elif result.dtype == np.object_ and non_default_dtype_backend:
            if not lib.is_datetime_array(result, skipna=True):
                dtype = StringDtype()
                cls = dtype.construct_array_type()
                result = cls._from_sequence(values, dtype=dtype)
    if dtype_backend == 'pyarrow':
        pa = import_optional_dependency('pyarrow')
        if isinstance(result, np.ndarray):
            result = ArrowExtensionArray(pa.array(result, from_pandas=True))
        elif isinstance(result, BaseMaskedArray):
            if result._mask.all():
                result = ArrowExtensionArray(pa.array([None] * len(result)))
            else:
                result = ArrowExtensionArray(pa.array(result._data, mask=result._mask))
        else:
            result = ArrowExtensionArray(pa.array(result.to_numpy(), from_pandas=True))
    return (result, na_count)

def _calc_rows(self, header: int | Sequence[int] | None, index_col: int | Sequence[int] | None, skiprows: Sequence[int] | int | Callable[[int], object] | None, nrows: int | None) -> int | None:
    """
        If nrows specified, find the number of rows needed from the
        file, otherwise return None.


        Parameters
        ----------
        header : int, list of int, or None
            See read_excel docstring.
        index_col : int, str, list of int, or None
            See read_excel docstring.
        skiprows : list-like, int, callable, or None
            See read_excel docstring.
        nrows : int or None
            See read_excel docstring.

        Returns
        -------
        int or None
        """
    if nrows is None:
        return None
    if header is None:
        header_rows = 1
    elif is_integer(header):
        header = cast('int', header)
        header_rows = 1 + header
    else:
        header = cast('Sequence', header)
        header_rows = 1 + header[-1]
    if is_list_like(header) and index_col is not None:
        header = cast('Sequence', header)
        if len(header) > 1:
            header_rows += 1
    if skiprows is None:
        return header_rows + nrows
    if is_integer(skiprows):
        skiprows = cast('int', skiprows)
        return header_rows + nrows + skiprows
    if is_list_like(skiprows):

        def f(skiprows: Sequence, x: int) -> bool:
            return x in skiprows
        skiprows = cast('Sequence', skiprows)
        return self._check_skiprows_func(partial(f, skiprows), header_rows + nrows)
    if callable(skiprows):
        return self._check_skiprows_func(skiprows, header_rows + nrows)
    return None

