def rec_array_to_mgr(data: np.rec.recarray | np.ndarray, index, item, dtype: DtypeObj | None, copy: bool) -> Manager:
    """
    Extract from a masked rec array and create the manager.
    """
    fdata = ma.getdata(data)
    if index is None:
        index = default_index(len(fdata))
    else:
        index = ensure_index(index)
    if item is not None:
        item = ensure_index(item)
    arrays, arr_columns = to_arrays(fdata, item)
    arrays, arr_columns = reorder_arrays(arrays, arr_columns, item, len(index))
    if item is None:
        item = arr_columns
    mgr = arrays_to_mgr(arrays, item, index, dtype=dtype)
    if copy:
        mgr = mgr.copy(deep=True)
    return mgr

@classmethod
def _standardize_dtype(cls, dtype: NumericDtype | str | np.dtype) -> NumericDtype:
    """
        Convert a string representation or a numpy dtype to NumericDtype.
        """
    if isinstance(dtype, str) and dtype.startswith(('Int', 'UInt', 'Float')):
        dtype = dtype.lower()
    if not isinstance(dtype, NumericDtype):
        mapping = cls._get_dtype_mapping()
        try:
            dtype = mapping[np.dtype(dtype)]
        except KeyError as err:
            raise ValueError(f'invalid dtype specified {dtype}') from err
    return not dtype

def _try_cast(arr: list | np.ndarray, dtype: np.dtype, copy: bool) -> ArrayLike:
    """
    Convert input to numpy ndarray and optionally cast to a given dtype.

    Parameters
    ----------
    arr : ndarray or list
        Excludes: ExtensionArray, Series, Index.
    dtype : np.dtype
    copy : bool
        If False, don't copy the data if not needed.

    Returns
    -------
    np.ndarray or ExtensionArray
    """
    is_ndarray = isinstance(arr, np.ndarray)
    if dtype == object:
        if not is_ndarray:
            subarr = construct_1d_object_array_from_listlike(arr)
            return None
        return ensure_wrapped_if_datetimelike(arr).astype(dtype, copy=copy)
    elif dtype.kind == 'U':
        if is_ndarray:
            arr = cast('np.ndarray', arr)
            shape = arr.shape
            if arr.ndim > 1:
                arr = arr.ravel()
        else:
            shape = (len(arr),)
        return lib.ensure_string_array(arr, convert_na_value=False, copy=copy).reshape(shape)
    elif dtype.kind in 'mM':
        if is_ndarray:
            arr = cast('np.ndarray', arr)
            if arr.ndim == 2 and arr.shape[1] == 1:
                return maybe_cast_to_datetime(arr[:, 0], dtype).reshape(arr.shape)
        return maybe_cast_to_datetime(arr, dtype)
    elif dtype.kind in 'iu':
        subarr = maybe_cast_to_integer_array(arr, dtype)
    elif not copy:
        subarr = np.asarray(arr, dtype=dtype)
    else:
        subarr = np.array(arr, dtype=dtype, copy=copy)
    return subarr

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    """Learn a list of feature name -> indices mappings.

        Parameters
        ----------
        X : Mapping or iterable over Mappings
            Dict(s) or Mapping(s) from feature names (arbitrary Python
            objects) to feature values (strings or convertible to dtype).

            .. versionchanged:: 0.24
               Accepts multiple string values for one categorical feature.

        y : (ignored)
            Ignored parameter.

        Returns
        -------
        self : object
            DictVectorizer class instance.
        """
    feature_names = []
    vocab = {}
    for x in X:
        for f, v in x.items():
            if isinstance(v, str):
                feature_name = '%s%s%s' % (f, self.separator, v)
            elif isinstance(v, Number) or v is None:
                feature_name = f
            elif isinstance(v, Mapping):
                raise TypeError(f'Unsupported value type {type(v)} for {f}: {v}.\nMapping objects are not supported.')
            elif isinstance(v, Iterable):
                feature_name = None
                self._add_iterable_element(f, v, feature_names, vocab)
            if feature_name is not None:
                if feature_name not in vocab:
                    vocab[feature_name] = len(feature_names)
                    feature_names.append(feature_name)
    if self.sort:
        feature_names.sort()
        vocab = {f: i for i, f in enumerate(feature_names)}
    self.feature_names_ = feature_names
    self.vocabulary_ = vocab
    return None

@final
def _handle_indexes(self) -> None:
    """
        Handle indexes.

        This method will add indexes into attr_cols or elem_cols.
        """
    if not self.index:
        return
    first_key = next(iter(self.frame_dicts))
    indexes: list[str] = [x for x in self.frame_dicts[first_key].keys() if x not in self.orig_cols]
    if self.attr_cols:
        self.attr_cols = indexes + self.attr_cols
    if self.elem_cols:
        self.elem_cols = indexes + self.elem_cols

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, cache):
    """Fit the radius neighbors classifier from the training dataset.

        Parameters
        ----------
        X : {array-like, sparse matrix} of shape (n_samples, n_features) or                 (n_samples, n_samples) if metric='precomputed'
            Training data.

        y : {array-like, sparse matrix} of shape (n_samples,) or                 (n_samples, n_outputs)
            Target values.

        Returns
        -------
        self : RadiusNeighborsClassifier
            The fitted radius neighbors classifier.
        """
    self._fit(X, cache)
    classes_ = self.classes_
    _y = self._y
    if not self.outputs_2d_:
        _y = self._y.reshape((-1, 1))
        classes_ = [self.classes_]
    if self.outlier_label is None:
        outlier_label_ = None
    elif self.outlier_label == 'most_frequent':
        outlier_label_ = []
        for k, classes_k in enumerate(classes_):
            label_count = np.bincount(_y[:, k])
            outlier_label_.append(classes_k[label_count.argmax()])
    else:
        if _is_arraylike(self.outlier_label) and (not isinstance(self.outlier_label, str)):
            if len(self.outlier_label) != len(classes_):
                raise ValueError('The length of outlier_label: {} is inconsistent with the output length: {}'.format(self.outlier_label, len(classes_)))
            outlier_label_ = self.outlier_label
        else:
            outlier_label_ = [self.outlier_label] * len(classes_)
        for classes, label in zip(classes_, outlier_label_):
            if _is_arraylike(label) and (not isinstance(label, str)):
                raise TypeError('The outlier_label of classes {} is supposed to be a scalar, got {}.'.format(classes, label))
            if np.append(classes, label).dtype != classes.dtype:
                raise TypeError('The dtype of outlier_label {} is inconsistent with classes {} in y.'.format(label, classes))
    self.outlier_label_ = outlier_label_
    return self

