        return self._from_pyarrow_array(pa_result)

def _yeo_johnson_inverse_transform(self, x, lmbda):
    """Return inverse-transformed input x following Yeo-Johnson inverse
        transform with parameter lambda.
        """
    x_inv = np.zeros_like(x)
    pos = x >= 0
    if abs(lmbda) < np.spacing(1.0):
        x_inv[pos] = np.exp(x[pos]) - 1
    else:
        x_inv[pos] = np.power(x[pos] * lmbda + 1, 1 / lmbda) - 1
    if abs(lmbda - 2) > np.spacing(1.0):
        x_inv[~pos] = 1 - np.power(-(2 - lmbda) * x[~pos] + 1, 1 / (2 - lmbda))
    else:
        x_inv[~pos] = 1 - np.exp(-x[~pos])
    return x_inv

def grouped_reduce(self, func: Callable) -> Self:
    """
        Apply grouped reduction function blockwise, returning a new BlockManager.

        Parameters
        ----------
        func : grouped reduction function

        Returns
        -------
        BlockManager
        """
    result_blocks: list[Block] = []
    for blk in self.blocks:
        if blk.is_object:
            for sb in blk._split():
                applied = sb.apply(func)
                result_blocks = extend_blocks(applied, result_blocks)
        else:
            applied = blk.apply(func)
            result_blocks = extend_blocks(applied, result_blocks)
    if len(result_blocks) == 0:
        nrows = 0
    else:
        nrows = result_blocks[0].values.shape[-1]
    index = default_index(nrows)
    return type(self).from_blocks(result_blocks, [self.axes[0].view(), index])

@final
def _reduceat_aggregate(self, values: np.ndarray, how: str, axis: AxisInt, min_count: int) -> np.ndarray | None:
    """
        Use ufunc.reduceat for sorted group ids.  Returns None to fall back.
        """
    info = self._reduceat_segment_info
    if info is None:
        return None
    na_count, group_starts, segment_ids, segment_sizes = info
    ngroups = self.ngroups
    orig_dtype = values.dtype
    if orig_dtype.kind == 'f' and np.isnan(values).any():
        return None
    if na_count > 0:
        if axis == 0:
            values = values[na_count:]
        else:
            values = values[:, na_count:]
    work_dtype: np.dtype
    if how == 'mean':
        work_dtype = np.dtype(np.float64)
    elif how in ('sum', 'prod') and orig_dtype.kind in 'ib':
        work_dtype = np.dtype(np.int64)
    elif how in ('sum', 'prod') and orig_dtype.kind == 'u':
        work_dtype = np.dtype(np.uint64)
    else:
        work_dtype = orig_dtype
    work_values = values.astype(work_dtype, copy=False)
    ufunc = _REDUCEAT_UFUNCS[how]
    seg = ufunc.reduceat(work_values, group_starts, axis=axis)
    if how == 'mean':
        sizes = segment_sizes.astype(np.float64)
        if seg.ndim == 1:
            seg = seg / sizes
        else:
            shape = [1] * seg.ndim
            shape[axis] = len(sizes)
            seg = seg / sizes.reshape(shape)
    res_dtype: np.dtype
    if how == 'mean':
        res_dtype = np.dtype(np.float64)
    elif how in ('sum', 'prod') and orig_dtype.kind == 'b':
        res_dtype = np.dtype(np.int64)
    else:
        res_dtype = orig_dtype
    out_shape = list(values.shape)
    out_shape[axis] = ngroups
    if how == 'sum':
        result = np.zeros(out_shape, dtype=work_dtype)
    elif how == 'prod':
        result = np.ones(out_shape, dtype=work_dtype)
    elif work_dtype.kind == 'f':
        result = np.full(out_shape, np.nan, dtype=work_dtype)
    elif work_dtype.kind == 'b':
        result = np.full(out_shape, how == 'min', dtype=work_dtype)
    else:
        iinfo = np.iinfo(work_dtype)
        fill = iinfo.max if how == 'min' else iinfo.min
        result = np.full(out_shape, fill, dtype=work_dtype)
    indexer: list[Any] = [slice(None)] * len(out_shape)
    indexer[axis] = segment_ids
    result[tuple(indexer)] = seg
    if how in ('sum', 'prod'):
        cutoff = max(0, min_count)
    else:
        cutoff = max(1, min_count)
    if cutoff > 0:
        group_counts = np.zeros(ngroups, dtype=np.int64)
        group_counts[segment_ids] = segment_sizes
        empty_mask = group_counts < cutoff
        if empty_mask.any():
            if result.dtype.kind in 'iub':
                result = result.astype(np.float64)
            indexer2: list[Any] = [slice(None)] * result.ndim
            indexer2[axis] = empty_mask
            result[tuple(indexer2)] = np.nan
    result = maybe_downcast_to_dtype(result, res_dtype)
    return result

def process_sampling_size(n: int | None, frac: float | None, replace: bool) -> int | None:
    """
    Process and validate the `n` and `frac` arguments to `NDFrame.sample` and
    `.GroupBy.sample`.

    Returns None if `frac` should be used (variable sampling sizes), otherwise returns
    the constant sampling size.
    """
    if n is None and frac is None:
        n = 1
    elif n is not None and frac is not None:
        raise ValueError('Please enter a value for `frac` OR `n`, not both')
    elif n is not None:
        if n < 0:
            raise ValueError('A negative number of rows requested. Please provide `n` >= 0.')
        if n % 1 != 0:
            raise ValueError('Only integers accepted as `n` values')
    else:
        assert frac is not None
        if frac > 1 and (not replace):
            raise ValueError('Replace has to be set to `True` when upsampling the population `frac` > 1.')
        if frac < 0:
            raise ValueError('A negative number of rows requested. Please provide `frac` >= 0.')
    return n

def dtypes(self, *, device=None, kind=None):
    """
        The array API data types supported by NumPy.

        Note that this function only returns data types that are defined by
        the array API.

        Parameters
        ----------
        device : str, optional
            The device to get the data types for. For NumPy, only ``'cpu'`` is
            allowed.
        kind : str or tuple of str, optional
            The kind of data types to return. If ``None``, all data types are
            returned. If a string, only data types of that kind are returned.
            If a tuple, a dictionary containing the union of the given kinds
            is returned. The following kinds are supported:

            - ``'bool'``: boolean data types (i.e., ``bool``).
            - ``'signed integer'``: signed integer data types (i.e., ``int8``,
              ``int16``, ``int32``, ``int64``).
            - ``'unsigned integer'``: unsigned integer data types (i.e.,
              ``uint8``, ``uint16``, ``uint32``, ``uint64``).
            - ``'integral'``: integer data types. Shorthand for ``('signed
              integer', 'unsigned integer')``.
            - ``'real floating'``: real-valued floating-point data types
              (i.e., ``float32``, ``float64``).
            - ``'complex floating'``: complex floating-point data types (i.e.,
              ``complex64``, ``complex128``).
            - ``'numeric'``: numeric data types. Shorthand for ``('integral',
              'real floating', 'complex floating')``.

        Returns
        -------
        dtypes : dict
            A dictionary mapping the names of data types to the corresponding
            NumPy data types.

        See Also
        --------
        __array_namespace_info__.capabilities,
        __array_namespace_info__.default_device,
        __array_namespace_info__.default_dtypes,
        __array_namespace_info__.devices

        Examples
        --------
        >>> info = np.__array_namespace_info__()
        >>> info.dtypes(kind='signed integer')
        {'int8': numpy.int8,
         'int16': numpy.int16,
         'int32': numpy.int32,
         'int64': numpy.int64}

        """
    if device not in ['cpu', None]:
        raise ValueError(f'Device not understood. Only "cpu" is allowed, but received: {device}')
    if kind is None:
        return {'bool': dtype(bool), 'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'bool':
        return {'bool': bool}
    if kind == 'signed integer':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64)}
    if kind == 'unsigned integer':
        return {'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'integral':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'real floating':
        return {'float32': dtype(float32), 'float64': dtype(float64)}
    if kind == 'complex floating':
        return {'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'numeric':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if isinstance(kind, tuple):
        res = {}
        for k in kind:
            res.update(self.dtypes(kind=k))
        return res
    raise ValueError(f'unsupported kind: {kind!r}')

