def _pandas_dtype_needs_early_conversion(pd_dtype):
    """Return True if pandas extension pd_dtype need to be converted early."""
    from pandas import SparseDtype
    from pandas.api.types import is_bool_dtype, is_float_dtype, is_integer_dtype
    if is_bool_dtype(pd_dtype):
        return True
    if isinstance(pd_dtype, SparseDtype):
        return False
    try:
        from pandas.api.types import is_extension_array_dtype
    except ImportError:
        return False
    if isinstance(pd_dtype, SparseDtype) or not is_extension_array_dtype(pd_dtype):
        return False
    elif is_float_dtype(pd_dtype):
        return True
    elif is_integer_dtype(pd_dtype):
        return True
    return False

def integer_repr(param_33):
    """Return the signed-magnitude interpretation of the binary representation
    of x."""
    import numpy as np
    if param_33.dtype == np.float16:
        return _integer_repr(param_33, np.int16, np.int16(-2 ** 15))
    elif param_33.dtype == np.float32:
        return _integer_repr(param_33, np.int32, np.int32(-2 ** 31))
    elif param_33.dtype == np.float64:
        return _integer_repr(param_33, np.int64, np.int64(-2 ** 63))
    else:
        raise ValueError(f'Unsupported dtype {param_33.dtype}')

def infer_dtype_from_scalar(val: object) -> tuple[DtypeObj, Any]:
    """
    Interpret the dtype from a scalar.

    Parameters
    ----------
    val : object
    """
    dtype: DtypeObj = _dtype_obj
    if isinstance(val, np.ndarray):
        if val.ndim != 0:
            msg = 'invalid ndarray passed to infer_dtype_from_scalar'
            raise ValueError(msg)
        dtype = val.dtype
        val = lib.item_from_zerodim(val)
    elif isinstance(val, str):
        dtype = _dtype_obj
        if using_string_dtype():
            from pandas.core.arrays.string_ import StringDtype
            dtype = StringDtype(na_value=np.nan)
    elif isinstance(val, (np.datetime64, dt.datetime)):
        try:
            val = Timestamp(val)
        except OutOfBoundsDatetime:
            return (_dtype_obj, val)
        if val is NaT or val.tz is None:
            val = val.to_datetime64()
            dtype = val.dtype
        else:
            dtype = DatetimeTZDtype(unit=val.unit, tz=val.tz)
    elif isinstance(val, (np.timedelta64, dt.timedelta)):
        try:
            val = Timedelta(val)
        except (OutOfBoundsTimedelta, OverflowError):
            dtype = _dtype_obj
        else:
            if val is NaT:
                val = np.timedelta64('NaT', 'ns')
            else:
                val = val.asm8
            dtype = val.dtype
    elif is_bool(val):
        dtype = np.dtype(np.bool_)
    elif is_integer(val):
        if isinstance(val, np.integer):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.int64)
        try:
            np.array(val, dtype=dtype)
        except OverflowError:
            dtype = np.array(val).dtype
    elif is_float(val):
        if isinstance(val, np.floating):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.float64)
    elif is_complex(val):
        dtype = np.dtype(np.complex128)
    if isinstance(val, Period):
        dtype = PeriodDtype(freq=val.freq)
    elif isinstance(val, Interval):
        subtype = infer_dtype_from_scalar(val.left)[0]
        dtype = IntervalDtype(subtype=subtype, closed=val.closed)
    return (dtype, val)

def validate_multiindex(self, obj: DataFrame | Series) -> tuple[DataFrame, list[Hashable]]:
    """
        validate that we can store the multi-index; reset and return the
        new object
        """
    levels = com.fill_missing_names(obj.index.names)
    if 'index' in levels:
        raise ValueError("cannot store a MultiIndex with a level named 'index' as a table; 'index' is reserved for the implicit row index")
    try:
        reset_obj = obj.reset_index()
    except ValueError as err:
        raise ValueError('duplicate names/columns in the multi-index when storing as a table') from err
    assert isinstance(reset_obj, DataFrame)
    return (reset_obj, levels)

def _safe_fill_null(arr: pa.Array | pa.ChunkedArray, fill_value: Any) -> pa.Array | pa.ChunkedArray:
    """
    Safe wrapper for pyarrow.compute.fill_null with fallback for Windows + pyarrow 21.

    pyarrow 21.0.0 on Windows has a bug in fill_null that incorrectly fills null values.
    This function uses a fallback implementation for that specific case, otherwise uses
    the standard pyarrow.compute.fill_null.

    Parameters
    ----------
    arr : pyarrow.Array | pyarrow.ChunkedArray
        Input array with potential null values.
    fill_value : Any
        Value to fill nulls with.

    Returns
    -------
    pyarrow.Array | pyarrow.ChunkedArray
        Array with nulls filled with fill_value.
    """
    import pyarrow.compute as pc
    is_windows = sys.platform in ['win32', 'cygwin']
    use_fallback = HAS_PYARROW and is_windows and (not pa_version_under21p0) and pa_version_under22p0
    if not use_fallback or isinstance(fill_value, (pa.Array, pa.ChunkedArray)):
        return pc.fill_null(arr, fill_value)
    fill_scalar = pa.scalar(fill_value, type=arr.type)
    if pa.types.is_duration(arr.type):

        def fill_null_duration(arr: pa.Array, fill_scalar: pa.Scalar) -> pa.Array:
            mask = pc.is_null(arr)
            zero_duration = pa.scalar(0, type=arr.type)
            arr_zeroed = pc.if_else(mask, zero_duration, arr)
            return pc.if_else(mask, fill_scalar, arr_zeroed)
        if isinstance(arr, pa.ChunkedArray):
            return pa.chunked_array([fill_null_duration(chunk, fill_scalar) for chunk in arr.chunks])
        return fill_null_duration(arr, fill_scalar)
    if isinstance(arr, pa.ChunkedArray):
        return pa.chunked_array([pc.if_else(pc.is_null(chunk), fill_scalar, chunk) for chunk in arr.chunks])
    return pc.if_else(pc.is_null(arr), fill_scalar, arr)

def convert_from_missing_indexer_tuple(field: tuple, axes: list[Index]) -> tuple:
    """
    Create a filtered indexer that doesn't have any missing indexers.
    """

    def get_indexer(_i, _idx):
        return axes[_i].get_loc(_idx['key']) if isinstance(_idx, dict) else _idx
    return tuple((get_indexer(_i, _idx) for _i, _idx in enumerate(field)))

def _finalize_columns_and_data(content: np.ndarray, columns: Index | None, dtype: DtypeObj | None) -> tuple[list[ArrayLike], Index]:
    """
    Ensure we have valid columns, cast object dtypes if possible.
    """
    contents = list(content.T)
    try:
        columns = _validate_or_indexify_columns(contents, columns)
    except AssertionError as err:
        raise ValueError(err) from err
    if contents and contents[0].dtype == np.object_:
        contents = convert_object_array(contents, dtype=dtype)
    return (contents, columns)

@final
def setitem(self, indexer, value):
    """
        Attempt self.values[indexer] = value, possibly creating a new array.

        This differs from Block.setitem by not allowing setitem to change
        the dtype of the Block.

        Parameters
        ----------
        indexer : tuple, list-like, array-like, slice, int
            The subset of self.values to set
        value : object
            The value being set

        Returns
        -------
        Block

        Notes
        -----
        `indexer` is a direct slice/positional indexer. `value` must
        be a compatible shape.
        """
    orig_indexer = indexer
    orig_value = value
    indexer = self._unwrap_setitem_indexer(indexer)
    value = self._maybe_squeeze_arg(value)
    values = self.values
    if values.ndim == 2:
        if not isinstance(indexer, tuple):
            indexer = (indexer, slice(None))
        if len(indexer) == 2:
            indexer = indexer[::-1]
        if isinstance(value, np.ndarray) and value.ndim == 2:
            value = value.T
    check_setitem_lengths(indexer, value, values)
    try:
        values[indexer] = value
    except (ValueError, TypeError):
        if isinstance(self.dtype, IntervalDtype):
            nb = self.coerce_to_target_dtype(orig_value, raise_on_upcast=True)
            return not nb.setitem(orig_indexer, orig_value)
        elif isinstance(self, NDArrayBackedExtensionBlock):
            nb = self.coerce_to_target_dtype(orig_value, raise_on_upcast=True)
            return nb.setitem(orig_indexer, orig_value)
        else:
            raise
    else:
        return self

